import React from 'react';
import './Services.css';
import { FaMobileAlt, FaLaptopCode, FaBullhorn, FaLayerGroup, FaPalette } from 'react-icons/fa';
const services=[{icon:<FaMobileAlt/>,number:'01',title:'Mobile app development',copy:'Native-feeling mobile products built to become part of someone’s everyday life.',className:'service-featured'},{icon:<FaLaptopCode/>,number:'02',title:'Web experiences',copy:'Fast, expressive websites that make complex ideas feel immediately clear.',className:'service-wide'},{icon:<FaLayerGroup/>,number:'03',title:'Product design',copy:'User-centered systems with a clear point of view.',className:''},{icon:<FaBullhorn/>,number:'04',title:'Digital growth',copy:'The focus and momentum to help your brand move forward.',className:''},{icon:<FaPalette/>,number:'05',title:'Brand identity',copy:'A visual language with enough character to be remembered.',className:'service-featured'}];
const Services=()=> <section className="services-section" id="services"><div className="services-glow glow-one"/><div className="services-glow glow-two"/><div className="services-heading"><div><p className="section-kicker">Capabilities / 01—05</p><h2>Strategy in motion.<br/><span>Craft in every pixel.</span></h2></div><p>We connect strategy, product, and technology into experiences that earn attention and create measurable momentum.</p></div><div className="services-bento">{services.map(service=><article key={service.number} className={`service-tile ${service.className}`}><div className="tile-top"><span>{service.number}</span><i>{service.icon}</i></div><h3>{service.title}</h3><p>{service.copy}</p><div className="tile-shine"/></article>)}</div></section>;
export default Services;
